const { existsSync } = await import('node:fs');
if (!existsSync(globalThis.input.image_path)) {
  throw new Error('Input image file does not exist');
}
globalThis.imagePath = globalThis.input.image_path;
globalThis.outputPath = '/tmp/out.pdf';

const { readFileSync, writeFileSync } = await import('node:fs');
const { PDFDocument } = await import('pdf-lib');
const imageBytes = readFileSync(globalThis.imagePath);
const pdfDoc = await PDFDocument.create();
const pngImage = await pdfDoc.embedPng(imageBytes);
const page = pdfDoc.addPage();
const { width, height } = page.getSize();
page.drawImage(pngImage, { x: 0, y: 0, width, height });
const pdfBytes = await pdfDoc.save();
writeFileSync(globalThis.outputPath, pdfBytes);
globalThis.pdfPath = globalThis.outputPath;
